 if(D.etapa==='elab'||D.etapa==='param'){const ok=D.etapa==='param'?['resumo','cad','plano','orc','staff','hist','sobre']:['resumo','cad','sobre'];t=t.filter(x=>ok.includes(x));if(!t.length)t=['sobre']}
