  TGRP.forEach(g=>{const l=g[1].filter(t=>ts.includes(t));if(!l.length)return;n+='<h6 style="margin-top:10px">'+g[0]+'</h6>'+l.map(t=>'<button role="tab" class="'+(S.tab===t&&!S.rel?'on':'')+'" data-a="tab" data-id="'+t+'">'+ic(TABI[t])+'<span>'+TABN[t]+'</span>'+badge(t)+'</button>').join('')});
