function gBusca(q){
 q=q.trim().toLowerCase();const r=$('#gsr');if(!q){r.style.display='none';return}
 const o=[];
 PROJ.filter(p=>(p.ativo!==false||has('ver_inativos'))&&(p.nome+' '+(p.pat||'')).toLowerCase().includes(q)).slice(0,5).forEach(p=>o.push('<button data-a="abrir" data-id="'+p.id+'"><b>'+esc(p.nome)+'</b><small>Projeto · '+esc(p.pat||'parceiro a definir')+'</small></button>'));
 if(S.view==='proj')tabsDisp().filter(t=>TABN[t].toLowerCase().includes(q)).forEach(t=>o.push('<button data-a="tab" data-id="'+t+'"><b>'+TABN[t]+'</b><small>Tela do projeto atual</small></button>'));
 if(has('acessos_admin')&&'acessos usuários perfis armazenamento'.includes(q))o.push('<button data-a="acessos"><b>Acessos e armazenamento</b><small>Administração</small></button>');
 r.innerHTML=o.join('')||'<div class="small muted" style="padding:10px 14px">Nada encontrado.</div>';r.style.display='block';
}
function badge(t){let n=0;if(t==='prest'&&has('lanc_analisa'))n=D.lanc.filter(l=>l.st==='lancado').length;if(t==='aud'&&has('aud_emite'))n=D.div.filter(d=>d.st==='respondida').length;if(t==='staff'){const ms=Object.keys(D.staffMes||{});if(has('staff_analisa'))n+=ms.filter(x=>D.staffMes[x].st==='em_analise').length;if(has('staff_prest'))n+=ms.filter(x=>D.staffMes[x].st==='devolvida').length}if(t==='orc'&&has('rem_aprova'))n=D.rem.filter(r=>r.st==='pendente').length;if(t==='prest'&&has('just_aprova'))n=D.lanc.filter(l=>l.cot&&l.cot.dispensa&&l.cot.justSt==='pendente').length;return n?' <span class="pill warn">'+n+'</span>':''}
function stepper(){const i=ETAPAS.findIndex(e=>e[0]===D.etapa);return'<div class="steps">'+ETAPAS.map((e,k)=>'<div class="step '+(k<i?'done':k===i?'cur':'')+'"><span class="no">'+(k<i?'✓':k+1)+'</span>'+e[1].slice(4)+'</div>').join('')+'</div>'}
function conformidade(){
 const env=D.lanc.filter(l=>l.st!=='rascunho'&&l.st!=='devolvido'),fotoV=env.filter(l=>verbaDe(l.v).foto),rc=env.filter(reqCot),rs=realizadas(e=>e.tipo==='aula');
 return[['Nota fiscal / recibo nos lançamentos enviados',env.filter(l=>l.docs.nf).length,env.length],['Comprovante de pagamento nos lançamentos enviados',env.filter(l=>l.docs.comp).length,env.length],['Foto nas compras que exigem foto',fotoV.filter(l=>l.docs.foto).length,fotoV.length],['Compras com 3 cotações ou justificativa aprovada',rc.filter(cotOk).length,rc.length],['Aulas realizadas com foto',rs.filter(e=>e.fotos>0).length,rs.length],['Alunos com termo de consentimento',D.alunos.filter(a=>a.termo).length,D.alunos.length]];
}
function pendRole(){
 const p=[];
 if(has('prest_enviar')){D.lanc.filter(l=>l.st==='devolvido').forEach(l=>p.push(['bad','Lançamento '+l.id+' devolvido: '+l.hist[l.hist.length-1].txt]));D.lanc.filter(l=>l.st==='rascunho').forEach(l=>p.push(['warn','Rascunho '+l.id+' ainda não lançado ('+l.desc+').']));D.div.filter(d=>d.st==='aberta').forEach(d=>p.push(['bad','Divergência '+d.id+' no lançamento '+d.l+': responder até '+fd(d.prazo)+'.']));if(prestSt(S.mes)==='aberta')p.push(['info','A prestação de '+mesNome(S.mes)+' ainda não foi enviada ao analista.'])}
 if(has('lanc_analisa')){const q=D.lanc.filter(l=>l.st==='lancado').length;if(q)p.push(['warn',q+' lançamento(s) aguardando sua conferência.']);Object.keys(D.prest).forEach(m=>{if(D.prest[m].st==='em_analise')p.push(['warn','Prestação de '+mesNome(m)+' em análise.'])})}
 if(has('just_aprova')){D.lanc.filter(l=>l.cot&&l.cot.dispensa&&l.cot.justSt==='pendente').forEach(l=>p.push(['warn','Justificativa de cotação do lançamento '+l.id+' aguardando sua decisão.']));D.rem.filter(x=>x.st==='pendente').forEach(x=>p.push(['warn','Remanejamento entre verbas de '+$$(x.valor,itemVerba(x.de))+' aguardando sua decisão.']));D.nc.filter(n=>n.st!=='encerrada').forEach(n=>p.push(['bad','Não conformidade aberta: '+n.desc]))}
 if(has('aud_emite')){D.div.filter(d=>d.st==='respondida').forEach(d=>p.push(['warn','Divergência '+d.id+' respondida: aguardando seu encerramento.']));D.div.filter(d=>d.st==='aberta').forEach(d=>p.push(['info','Divergência '+d.id+' aguardando resposta (prazo '+fd(d.prazo)+').']))}
 if(has('proj_gerir')){const s=D.alunos.filter(a=>!a.termo).length;if(s)p.push(['warn',s+' aluno(s) sem termo de consentimento.']);D.cal.filter(e=>e.st==='realizada'&&e.tipo==='aula'&&e.fotos===0).forEach(e=>p.push(['warn','Aula de '+fd(e.data)+' sem foto.']))}
 if(has('acomp_prof')){D.cal.filter(e=>e.data>=HOJE&&e.st==='prevista'&&e.inst===userAtual().nome).slice(0,3).forEach(e=>p.push(['info','Próxima aula: '+fd(e.data)+' às '+e.hora+' ('+acaoDe(e.acao).nome+').']))}
 return p;
}
