 if(e==='elab')return[['Edital carregado',D.docs.some(x=>x.t==='Edital')],['Responsável pela elaboração e condução',!!D.respElab],['Cliente / parceiro',!!D.pat],['Instrumento e códigos do parceiro',!!D.instr&&D.codigos.length>0],['Caracterização do projeto',!!D.tipo],['Período do projeto e objetivo',!!D.ini&&!!D.fim&&!!D.objetivo]];
