 return[['Ao menos uma conta bancária',D.contas.some(contaAtiva)],['Ao menos um centro de custo',D.cc.some(contaAtiva)],['Plano com ao menos uma ação',D.acoes.length>0],['Toda ação com ao menos uma meta',D.acoes.length>0&&D.acoes.every(a=>a.metas.length>0)],['Orçamento por verba e itens definido',totalOrc()>0],['Todo item de custo com 3 orçamentos ou justificativa aprovada pelo gestor',D.verbas.length>0&&itensCot().every(cotOkItem)],['Critérios da auditoria com pesos somando 100%',sum(D.criterios.map(c=>c.peso))===100]];
