 L.push('Total do mês: '+brl(sum(d.ap.map(l=>l.valor))));L.push('');
 L.push('2. AULAS E AÇÕES');L.push('Previstas: '+d.au.length+' | Realizadas: '+d.re.length+' | Canceladas: '+d.canc.length+' | Frequência média: '+pc(d.fq));d.canc.forEach(e=>L.push('- Cancelada em '+fd(e.data)+': '+e.motivo));
